import React, { useEffect, useState } from "react";
import axios from "axios";

export default function ParentFeePage() {
  const [fee, setFee] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchFees = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/fees");
        console.log("📡 API Response:", res.data); // Debug log

        if (res.data.success && res.data.data) {
          setFee(res.data.data);
        } else {
          setError("No fee data found.");
        }
      } catch (err) {
        console.error("❌ Error fetching fees:", err);
        setError("Failed to load fee structure.");
      }
    };

    fetchFees();
  }, []);

  if (error) return <p style={{ color: "red" }}>{error}</p>;
  if (!fee) return <p>Loading...</p>;

  return (
    <div style={{ padding: "20px", maxWidth: "700px", margin: "auto" }}>
      <h2>Fee Structure ({fee.academicYear})</h2>
      <div dangerouslySetInnerHTML={{ __html: fee.notes }} />

      <table
        style={{
          width: "100%",
          borderCollapse: "collapse",
          marginTop: "20px",
          border: "1px solid #ccc",
        }}
      >
        <thead style={{ background: "#f5f5f5" }}>
          <tr>
            <th style={{ border: "1px solid #ccc", padding: "10px" }}>Particulars</th>
            <th style={{ border: "1px solid #ccc", padding: "10px" }}>Amount (₹)</th>
          </tr>
        </thead>
        <tbody>
          {fee.items.map((item) => (
            <tr key={item.key}>
              <td style={{ border: "1px solid #ccc", padding: "10px" }}>{item.title}</td>
              <td style={{ border: "1px solid #ccc", padding: "10px" }}>{item.amount}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h3 style={{ textAlign: "right", marginTop: "10px" }}>
        Total: ₹
        {fee.items.reduce((sum, i) => sum + i.amount, 0)}
      </h3>
    </div>
  );
}
